const page=usePage(), user=computed(()=>page.props.auth?.user),open=ref(false),bell=ref(false),online=ref(navigator.onLine);const net=()=>online.value=navigator.onLine;onMounted(()=>{addEventListener('online',net);addEventListener('offline',net)});onUnmounted(()=>{removeEventListener('online',net);removeEventListener('offline',net)});
